static void test_l91_math_fixed(void) {
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("(1px + 2px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("1px"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px))"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc()"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("min()"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px,2px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("foo(1px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px) "));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("clamp(1px, 2px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px 2px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(-)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px * 2px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(2 / 1px)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1deg + 1s)"));
    TEST_ASSERT_EQUAL(WF_CSSPROP_BAD, wf_cssprop_math_type("calc(1px + 0)"));
}

